function renderTable(){const reviewBody=$('reviewBody'),body=$('scheduleBody');reviewBody.innerHTML='';body.innerHTML='';const needs=state.events.filter(e=>eventIssues(e).length);needs.forEach(e=>reviewBody.appendChild(buildEventRow(e)));$('reviewSectionCount').textContent=needs.length;$('reviewTableWrap').classList.toggle('cb-hidden',!needs.length);$('reviewEmpty').classList.toggle('is-visible',!needs.length);const f=$('filterFaculty').value,q=$('searchEvents').value.toLowerCase();state.events.filter(e=>!eventIssues(e).length).filter(e=>{const ids=e.facultyIds||[],ok=f==='all'||ids.includes(f)||(f==='assessment'&&['assessment','activity'].includes(e.type))||(f==='Excluded'&&!e.include);return ok&&e.topic.toLowerCase().includes(q)}).forEach(e=>body.appendChild(buildEventRow(e)));updateMetrics()}
function lectureCompleteness(){const eligible=state.events.filter(e=>e.lectureSource==='header');if(!eligible.length)return null;const nums=eligible.map(e=>/^\d+$/.test(e.lecture)?+e.lecture:null).filter(Number.isFinite);if(nums.length<3)return null;const max=Math.max(...nums),set=new Set(nums),missing=[];for(let i=1;i<=max;i++)if(!set.has(i))missing.push(i);const dup=[...new Set(nums.filter((n,i,a)=>a.indexOf(n)!==i))];return{max,missing,dup}}
function updateMetrics(){$('metricEvents').textContent=state.events.length;$('metricFaculty').textContent=state.faculty.length;$('metricReview').textContent=state.events.filter(e=>eventIssues(e).some(x=>x!=='inferred-time')).length;$('metricIncluded').textContent=state.events.filter(e=>e.include).length;$('metricInferred').textContent=state.events.filter(e=>e.timeSource==='inferred').length;const c=lectureCompleteness(),box=$('completenessNotice');if(!c){box.innerHTML='';return}if(c.missing.length||c.dup.length){box.className='ft-notice ft-notice-warning cb-completeness';box.innerHTML=`<strong>! Schedule completeness check</strong><br><span class="ft-muted">${c.missing.length?`Lecture number${c.missing.length===1?'':'s'} ${c.missing.join(', ')} ${c.missing.length===1?'was':'were'} not detected. `:''}${c.dup.length?`Duplicate lecture number${c.dup.length===1?'':'s'}: ${c.dup.join(', ')}.`:''} Review the source schedule before export.</span>`}else{box.className='ft-notice ft-notice-success cb-completeness';box.innerHTML=`<strong>✓ Lecture sequence appears complete</strong><br><span class="ft-muted">CalendarBridge detected lecture numbers 1–${c.max} without gaps.</span>`}}
