function renderFacultyEditor(){ensureV6State();const box=$('facultyEditor');box.innerHTML='';state.faculty.forEach((f,i)=>{const isCoord=(state.coordinatorIds||[]).includes(f.id);const row=document.createElement('div');row.className='cb-faculty-edit-row';const role=isCoord?'Course Coordinator':'Course Faculty';row.innerHTML=`<div class="ft-field"><label>${role}</label><input class="ft-input f-short" value="${esc(f.short)}"></div><div class="ft-field"><label>Name</label><input class="ft-input f-name" value="${esc(f.name)}"></div><div class="ft-field"><label>Email</label><input class="ft-input f-email" type="email" value="${esc(f.email)}"></div><div class="cb-btn-row"><button class="ft-btn f-coordinator">${isCoord?'Remove coordinator role':'Add coordinator'}</button><button class="ft-btn ft-btn-danger f-remove">Remove</button></div>`;row.querySelector('.f-short').onchange=x=>{f.short=clean(x.target.value)||`Faculty ${i+1}`;refreshFacultyOptions();renderTable()};row.querySelector('.f-name').onchange=x=>{f.name=clean(x.target.value);renderTable()};row.querySelector('.f-email').onchange=x=>f.email=clean(x.target.value);row.querySelector('.f-coordinator').onclick=()=>{const ids=new Set(state.coordinatorIds||[]);if(isCoord)ids.delete(f.id);else ids.add(f.id);state.coordinatorIds=[...ids];state.coordinatorId=state.coordinatorIds[0]||null;renderFacultyEditor();renderTable();renderExportSummary();showToast(isCoord?`${f.short||f.name||'Faculty member'} removed as course coordinator.`:`${f.short||f.name||'Faculty member'} added as course coordinator.`)};row.querySelector('.f-remove').onclick=()=>{state.events.forEach(e=>e.facultyIds=(e.facultyIds||[]).filter(id=>id!==f.id));state.faculty=state.faculty.filter(v=>v.id!==f.id);state.coordinatorIds=(state.coordinatorIds||[]).filter(id=>id!==f.id);state.coordinatorId=state.coordinatorIds[0]||null;renderFacultyEditor();refreshFacultyOptions();renderTable()};box.appendChild(row)})}

function splitPatternParts(value){
 const raw=normalizeDashes(clean(value).replace(/\./g,':'));
 const m=raw.match(/^\s*(\d{1,2}:\d{2})\s*(AM|PM)?\s*–\s*(\d{1,2}:\d{2})\s*(AM|PM)?\s*$/i);
 if(!m)return{start:'',startMer:'',end:'',endMer:''};
 let startMer=(m[2]||'').toUpperCase(),endMer=(m[4]||'').toUpperCase();
 if(!startMer&&endMer)startMer=endMer;
 if(!endMer&&startMer)endMer=startMer;
 return{start:m[1],startMer,end:m[3],endMer};
}
function periodString(p){
 const start=clean(p?.start),end=clean(p?.end),sm=clean(p?.startMer).toUpperCase(),em=clean(p?.endMer).toUpperCase();
 if(!start&&!end)return'';
 return clean(`${start}${sm?' '+sm:''} – ${end}${em?' '+em:''}`);
}
function renderMeetingPatterns(){
  const host=$('meetingPatternEditor');
  if(!host)return;
  const days=['Monday','Tuesday','Wednesday','Thursday','Friday'];
  host.innerHTML='';
  const missing=[];
  days.forEach(day=>{
    const vals=state.meetingPatterns?.[day]||[];
    if(!vals.length&&!expandedMeetingDays.has(day)){missing.push(day);return}
    const wrap=document.createElement('div');
    wrap.className='cb-meeting-day';
    const periods=(vals.length?vals.map(splitPatternParts):[{start:'',startMer:'',end:'',endMer:''}]);
    wrap.innerHTML=`<strong>${day}</strong><div class="periodHost"></div><button type="button" class="ft-btn cb-add-period">+ Add period</button><div class="cb-pattern-source">${vals.length?`${vals.length} detected period${vals.length===1?'':'s'}${periods.some(p=>!p.startMer||!p.endMer)?' · AM/PM needed':''}`:'Manual period — enter start/end time'}</div>`;
    const ph=wrap.querySelector('.periodHost');
    const save=()=>{state.meetingPatterns[day]=periods.map(periodString).filter(Boolean)};
    const draw=()=>{
      ph.innerHTML='';
      periods.forEach((p,i)=>{
        const row=document.createElement('div');
        row.className='cb-period-row';
        row.innerHTML=`<div class="cb-time-line"><span class="cb-time-label">Start</span><input class="ft-input p-start" aria-label="${day} start time" placeholder="9:40" value="${esc(p.start)}"><button type="button" class="ft-btn cb-meridiem p-sm">${p.startMer||'AM/PM'}</button></div><div class="cb-time-line"><span class="cb-time-label">End</span><input class="ft-input p-end" aria-label="${day} end time" placeholder="10:40" value="${esc(p.end)}"><button type="button" class="ft-btn cb-meridiem p-em">${p.endMer||'AM/PM'}</button></div><button type="button" class="ft-btn cb-period-remove" aria-label="Remove ${day} period">×</button>`;
        row.querySelector('.p-start').onchange=e=>{p.start=clean(e.target.value);save()};
        row.querySelector('.p-end').onchange=e=>{p.end=clean(e.target.value);save()};
        const toggle=(key,btn)=>{p[key]=p[key]==='AM'?'PM':'AM';btn.textContent=p[key];save()};
        row.querySelector('.p-sm').onclick=e=>toggle('startMer',e.currentTarget);
        row.querySelector('.p-em').onclick=e=>toggle('endMer',e.currentTarget);
        row.querySelector('.cb-period-remove').onclick=()=>{
          periods.splice(i,1);save();
          if(!periods.length){expandedMeetingDays.delete(day);renderMeetingPatterns();return}
          draw();
        };
        ph.appendChild(row)
      })
    };
    draw();
    wrap.querySelector('.cb-add-period').onclick=()=>{periods.push({start:'',startMer:'',end:'',endMer:''});draw()};
    host.appendChild(wrap)
  });
  if(missing.length){
    const collapsed=document.createElement('div');
    collapsed.className='cb-undetected-days';
    collapsed.innerHTML='<span class="cb-undetected-label">Not detected:</span>';
    missing.forEach(day=>{
      const btn=document.createElement('button');
      btn.type='button';btn.className='cb-day-pill';
      btn.setAttribute('aria-label',`Add recurring ${day} period`);
      btn.innerHTML=`<span>+ ${day}</span><span class="cb-day-pill-note">add period</span>`;
      btn.onclick=()=>{expandedMeetingDays.add(day);renderMeetingPatterns()};
      collapsed.appendChild(btn)
    });
    host.appendChild(collapsed)
  }
}
function applyMeetingPatterns(){state.meetingLocation=clean($('meetingLocation').value);const validSlots=Object.values(state.meetingPatterns||{}).flat().filter(Boolean),invalid=validSlots.filter(v=>!parseTimeRange(v));if(invalid.length){alert('Please choose AM or PM for every recurring start and end time before applying the schedule.');return}const affected=state.events.filter(e=>e.include&&e.type!=='assessment'&&state.meetingPatterns?.[e.day||dayFromDate(e.date)]?.length).length;if(!confirm(`Apply the high-level course schedule?\n\nThis will replace the start and end times for ${affected} matching non-assessment event${affected===1?'':'s'} in the detailed schedule. Explicit special-event times such as exams are preserved.\n\nThe recurring location will also be applied when one is entered.`))return;if(state.meetingLocation){state.events.forEach(e=>{if(e.include&&e.type!=='no-class'){e.location=state.meetingLocation;e.locationSource='confirmed-schedule'}})}const byDate={};state.events.forEach(e=>{if(!e.include||e.type==='assessment'||e.type==='no-class')return;if(!e.day)e.day=dayFromDate(e.date);if(!e.day)return;(byDate[e.date]??=[]).push(e)});for(const evs of Object.values(byDate)){const day=evs[0].day||dayFromDate(evs[0].date),slots=state.meetingPatterns?.[day]||[];if(!slots.length)continue;evs.forEach((e,i)=>{const slot=slots[Math.min(i,slots.length-1)];if(slot&&parseTimeRange(slot)){e.time=slot;e.timeSource='confirmed-schedule';e.timeConfirmed=true}})}renderTable();showToast('High-level schedule confirmed and applied. Review the detailed schedule before export.')}
function renderRevisionPanel(){const panel=$('revisionPanel');if(!panel)return;if(!state.revision){panel.classList.remove('is-visible');return}panel.classList.add('is-visible');const c=state.revision.counts||{};$('revAdded').textContent=c.added||0;$('revChanged').textContent=c.changed||0;$('revRemoved').textContent=c.removed||0;$('revUnchanged').textContent=c.unchanged||0;$('revisionSummary').textContent=`Compared ${state.revision.baseSource||'saved project'} with ${state.revision.currentSource||state.sourceName}.`;if($('downloadRemovedReport'))$('downloadRemovedReport').disabled=!(state.revision.removed||[]).length}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
