function saveProject(){ensureV6State();const copy=structuredClone(state);copy.savedAt=new Date().toISOString();copy.projectVersion="7.5.9";const blob=new Blob([JSON.stringify(copy,null,2)],{type:'application/json'});downloadBlob(blob,`${safeFile(state.course.code||'Course')}-CalendarBridge-v7.5.9-project.json`);showToast('CalendarBridge project saved.')}
function sortEvents(a,b){const da=parseDateParts(a.date),db=parseDateParts(b.date),va=da?new Date(da.y,da.mo-1,da.d).getTime():0,vb=db?new Date(db.y,db.mo-1,db.d).getTime():0;if(va!==vb)return va-vb;const ta=parseTimeRange(a.time)?.start,tb=parseTimeRange(b.time)?.start;return ((ta?.h||0)*60+(ta?.min||0))-((tb?.h||0)*60+(tb?.min||0))}

